<script setup lang="ts">
import {ref,watch} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;initialModule?:string}>();const modules=ref<any[]>([]);const requests=ref<any[]>([]);const runs=ref<any[]>([]);const module=ref(props.initialModule||'disaster_limit');watch(()=>props.initialModule,value=>{if(value)module.value=value});const run=ref('');const parameters=ref('{}');const selected=ref<any>(null);const error=ref('');const busy=ref(false);
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
const taskStatus:Record<string,string>={prepared:'输入已就绪',succeeded:'计算完成',failed:'计算失败'};
const topic2=ref<any[]>([]);const statusNames:Record<string,string>={integrated:'已接入',simplified:'简化算法',awaiting_artifacts:'待补冻结成果',research_only:'研究脚本待任务接入'};
async function refresh(){const id=props.projectId;if(!id)return;const data=await Promise.all([api('/api/integration/modules'),api('/api/integration/requests?project_id='+id),api('/api/runs?project_id='+id),api('/api/integration/topic2')]);if(id===props.projectId){[modules.value,requests.value,runs.value,topic2.value]=data}}
watch(()=>props.projectId,()=>{selected.value=null;run.value='';requests.value=[];runs.value=[];refresh().catch(e=>error.value=String(e))},{immediate:true});
async function create(){const id=props.projectId;busy.value=true;error.value='';try{const values=JSON.parse(parameters.value);if(!values||Array.isArray(values)||typeof values!=='object')throw Error('模块参数必须是JSON对象');const project=await api('/api/projects/'+id);const source=run.value?await api('/api/runs/'+run.value):null;const d=await api('/api/integration/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:module.value,project_id:id,project_revision:project.revision,source_run_id:source?.id||null,scenario_id:source?.scenario_id||null,parameters:values})});if(id===props.projectId){selected.value=d;await refresh()}}catch(e){if(id===props.projectId)error.value=String(e)}finally{busy.value=false}}
async function inspect(id:string){const project=props.projectId;const d=await api('/api/integration/requests/'+id);if(project===props.projectId)selected.value=d}
function download(){const blob=new Blob([JSON.stringify(selected.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='模块交接-'+selected.value.id.slice(0,8)+'.json';a.click();URL.revokeObjectURL(url)}
async function execute(){busy.value=true;error.value='';const id=props.projectId;try{const d=await api('/api/integration/requests/'+selected.value.id+'/execute',{method:'POST'});if(id===props.projectId){selected.value=d;await refresh()}}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><article id="integration-catalog"><h3>课题2接入清单</h3><table><tr><th>能力</th><th>状态</th><th>边界与待补项</th></tr><tr v-for="item in topic2"><td>{{item.name}}</td><td>{{statusNames[item.status]}}</td><td>{{item.scope}}</td></tr></table></article><article id="integration-modules"><h3>模块算法与接口</h3><p>课题2计算在对应业务菜单运行。以下接口供承灾、离网、黑启动与一二次协同规划接入，采用统一工程、场景、基准结果和单位口径。未注册算法时只能生成交接包。</p><table><tr><th>模块</th><th>输入约定</th><th>输出约定</th><th>算法状态</th></tr><tr v-for="m in modules"><td>{{m.name}}</td><td>{{m.input.join('、')}}</td><td>{{m.output.join('、')}}</td><td>{{m.adapter_version||'待接入'}}</td></tr></table><p><a href="/api/integration/schema" target="_blank">查看版本1.0输入输出JSON Schema</a> · <a href="/openapi.json" target="_blank">完整API定义JSON</a> · <a href="/api/backup">备份已保存数据</a></p></article><article id="integration-requests"><h3>生成模块交接任务</h3><p>请先保存工程。交接包冻结已保存工程及所选基准，不会用当前草稿覆盖历史计算。基准计算的场景自动随包传递。</p><label class="field">目标模块<select v-model="module"><option v-for="m in modules" :value="m.id">{{m.name}}</option></select></label><label class="field">基准计算<select v-model="run"><option value="">仅已保存工程</option><option v-for="r in runs" :value="r.id">{{r.created}} · {{r.id.slice(0,8)}}</option></select></label><label>模块参数 / JSON<textarea v-model="parameters" spellcheck="false"></textarea></label><button @click="create" :disabled="busy||!projectId">保存输入快照与交接任务</button><p class="error" v-if="error">{{error}}</p><h3>交接档案</h3><button class="record" v-for="r in requests" @click="inspect(r.id).catch(e=>error=String(e))">{{modules.find(m=>m.id===r.module)?.name}} · {{r.created}} · {{taskStatus[r.status]||r.status}}</button><template v-if="selected"><p>任务 {{selected.id}} · {{taskStatus[selected.status]||selected.status}}；输入摘要 {{selected.request_sha256.slice(0,16)}}</p><button @click="download">导出完整交接JSON</button><button @click="execute" :disabled="busy||!!selected.result||!modules.find(m=>m.id===selected.module)?.adapter_version">调用已注册算法</button><p v-if="selected.result_origin==='external_import_unverified'">此结果为外部导入，尚未经平台独立校验。</p><details><summary>输入与结果快照</summary><pre>{{JSON.stringify(selected,null,2)}}</pre></details></template></article></template>
<style scoped>select{max-width:65%;padding:8px}pre{white-space:pre-wrap;max-height:500px;overflow:auto}</style>
